// exactly 42 lines of code ;-P
#define C_ 67
#define h_ 104
#define a_ 97
#define s_ 115
#define d_ (68+32)
#define e_ (69+32)
#define o_ (79+32)
#define SDFFontTex iChannel0
float getCharDist(int c, vec2 p)  // p=[(-.5,-.5)..(.5,.5)]
{
    vec2 r=vec2(textureSize(SDFFontTex,0));
    float d=textureLod(SDFFontTex,vec2(c%16,15-c/16)/16.+vec2(0,1)+clamp((p+.5)/16.,1./r,1.-1./r),0.).w-.5;
    vec2  d2=abs(p)-(.5-1./r);
    if (d2.x>0. || d2.y>0.) return d+max(d2.x,d2.y);
    return d-.02;
}
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void mainImage( out vec4 fragColor, vec2 fragCoord )
{
    int lnum=7;
    int l[7]=int[7](C_,h_,a_,s_,s_,e_,32);
    vec3 col=vec3(0);
    float csize=52.*iResolution.y/500.;
    float d=1000.;
    float y0=csize*.5;
    for(int i=0;i<42;i++){
        vec2 fc=fragCoord;
        csize*=.932;
        fc.x+=iTime*4.*csize+texelFetch(iChannel1,ivec2(i,0),0).x*csize*15.;
        float cx=fc.x/csize*2.;
        vec2 cc=(fc-vec2(0,y0+sin(fc.x*1.3/csize+iTime*12.+float(i))*csize*.1))/(csize*vec2(.5,1));
        cc.x=(fract(cc.x)-.5)*.5;
        float dp=d;
        d=min(d,getCharDist(l[int(cx)%lnum],cc)*csize);
        if (dp!=d) col=hsv2rgb(vec3(float(i)*.3,.7,.7));
        y0+=csize*.7;
    }
    //onderstaand de oude regel
    //fragColor=vec4(col+abs(d+.5)-.5,1);

    //onderstaand nieuwe regel om achtergrond zwart te maken met behulp van chatgpt
    fragColor=vec4(col * step(0.0, -d), 1); // Zwarte achtergrond behouden door kleur toe te passen alleen waar nodig.


} //...really 42 now ...was not the hardest codegolf-fight ;-)
